/// <summary>
/// Charge through lines creation class
/// MPJ_37288_ChargebackChargethrough_extension (MPJ_3587)
/// </summary>
public class METCBCTInvoiceLinesCreation
{
}

Method.Source:
    /// <summary>
    /// Entry point of the class
    /// </summary>
    /// <param name="args"><c>Args</c></param>
    static void main(Args args)
    {
        METCBCTInvoiceLinesCreation ctInvoiceLinesCreation = METCBCTInvoiceLinesCreation::construct();
        FormDataSource              formDataSource;
        METCBCTInvoiceHeaderTable   invoiceHeaderTable;
        Common                      common;
        common = args.record();        
        if (common.TableId  == tableNum(METCBCTInvoiceHeaderTable))           
        {
            invoiceHeaderTable = args.record();
            if (invoiceHeaderTable.Status == METCBCTInvoiceStatus::Processed)
            {
                throw Error("@MET:ChargethroughInvoiceIsAlreadyProcessed");
            }

            ctInvoiceLinesCreation.createMETCBCTInvoiceLine(args.record());
        }
        else
        {
            throw error(strfmt("@SYS19306","@MET:Posting"));
        }
    
        if (FormDataUtil::isFormDataSource(args.record()))
        {
            formDataSource = FormDataUtil::getFormDataSource(args.record());
            formDataSource.research(true);
        }
    }

/// <summary>
///  Create a new instance of  METCBCTInvoiceCreation class
/// </summary>
/// <returns>
/// A new instance of METCBCTInvoiceCreation class
/// </returns>
public static METCBCTInvoiceLinesCreation construct()
{
    return new METCBCTInvoiceLinesCreation();
}

    /// <summary>
    ///  Create Records in METCBCTInvoiceLine
    /// </summary>
    /// <param name="_cbCTInvoiceHeaderTable"><c>METCBCTInvoiceHeaderTable</c></param>
    /// <returns>True if all CT lines are successfully created; otherwise, false.</returns>
    public boolean createMETCBCTInvoiceLine(METCBCTInvoiceHeaderTable _cbCTInvoiceHeaderTable)
    {
        boolean             ret = true;       
        METCBCTInvoiceLine  metCBCTInvoiceLine;

        int fromInfologLine = infologLine();
        fromInfologLine = fromInfologLine == 0 ? fromInfologLine : fromInfologLine + 1;

        ttsbegin;
        if (_cbCTInvoiceHeaderTable)
        {
            _cbCTInvoiceHeaderTable.selectForUpdate(true);
            _cbCTInvoiceHeaderTable.ErrorDescription = METConstants::emptyString;
            _cbCTInvoiceHeaderTable.Error = NoYes::No;
            _cbCTInvoiceHeaderTable.update();
        }

        if (METCBCTInvoiceLine::exist(_cbCTInvoiceHeaderTable.Number))
        {
            // Show dialog only when this is called from screen, not from interface/data entity
            if (FormDataUtil::isFormDataSource(_cbCTInvoiceHeaderTable))
            {
                boolean confirm = Box::yesNo("@MET:DeleteInvoiceLines",DialogButton::No);
                if(confirm)
                {
                    delete_from metCBCTInvoiceLine
                    where metCBCTInvoiceLine.HeaderNumber == _cbCTInvoiceHeaderTable.Number;
                }
                else
                {
                    Info("@MET:NoRecordsDeleted");
                }
            }
            else
            {
                delete_from metCBCTInvoiceLine
                    where metCBCTInvoiceLine.HeaderNumber == _cbCTInvoiceHeaderTable.Number;
            }
        }   
        
        if (_cbCTInvoiceHeaderTable.VendInvoiceGSTAmount <= (_cbCTInvoiceHeaderTable.VendInvoiceAmtInclGST - _cbCTInvoiceHeaderTable.VendInvoiceGSTAmount))
        {  
            //Percent gstPercent = this.getGSTPercentage(_metCBCTInvoiceHeaderTable);
            Percent gstPercent = _cbCTInvoiceHeaderTable.getGSTPercentage();
            
            if (gstPercent <= 10)
            {
                ret = this.handleInvoiceLineCreation(_cbCTInvoiceHeaderTable,gstPercent);
            }
            else
            {                
                error("@MET:GSTPercentageIsMoreThan10Pct");
                ret = false;
            }             
        }
        else
        {
            error("@MET:GSTPercentageIsMoreThanNetInvoiceAmount");
            ret = false;
        }

        if (!ret)
        {
            // Save infolog in the error description field
            _cbCTInvoiceHeaderTable.selectForUpdate(true);
            _cbCTInvoiceHeaderTable.captureFromInfolog(fromInfologLine);

            // Bug_188467_CB411_ChargethroughIssueFix
            _cbCTInvoiceHeaderTable.update();

            delete_from METCBCTInvoiceLine where METCBCTInvoiceLine.HeaderNumber == _cbCTInvoiceHeaderTable.Number;
        }

        ttscommit;

        return ret;
    }

/// <summary>
///  calculate GST percentage
/// </summary>
/// <returns>
/// return real
/// </returns>
/// <param name="_metCBCTInvoiceHeaderTable"><c>METCBCTInvoiceHeaderTable</c></param>
public  amount getRemainingBaseAmount(METCBCTInvoiceHeaderTable _metCBCTInvoiceHeaderTable)
{
    Amount  baseAmountForGST    = _metCBCTInvoiceHeaderTable.VendInvoiceGSTAmount*10;
    Amount  remainingBaseAmount = _metCBCTInvoiceHeaderTable.VendInvoiceAmtInclGST-baseAmountForGST-_metCBCTInvoiceHeaderTable.VendInvoiceGSTAmount;
    return remainingBaseAmount;
}

    /// <summary>
    /// Create invoice line
    /// </summary>    
    /// <param name="_metCBCTInvoiceHeaderTable"><c>METCBCTInvoiceHeaderTable</c></param>
    /// <param name="_metCBCTVendCust"><c>METCBCTVendCust</c></param>
    /// <param name="_amount"><c>amount</c></param>
    /// <param name="_taxGroup"><c>line creation gst group</c></param>
    /// <param name="_allocItemId"><c>Item id from allocation</c></param>
    /// <returns>True if CT line is successfully created; otherwise, false.</returns>
    public boolean createInvoiceLine(METCBCTInvoiceHeaderTable _metCBCTInvoiceHeaderTable, 
                                   METCBCTVendCust _metCBCTVendCust, 
                                   Amount _amount, 
                                   //TaxItemGroup _gstGroup='',
                                   TaxGroup _taxGroup = '',
                                   ItemId _allocItemId = '')
    {
        METCBCTInvoiceLine  metCBCTInvoiceLine;        
        boolean             ret = true;
        CustTable           custTable               = CustTable::find(_metCBCTInvoiceHeaderTable.CustomerAccount); 
        VendTable           vendTable               = VendTable::find(_metCBCTInvoiceHeaderTable.VendorAccount);
        METVendTable        metVendTable            = METVendTable::find(vendTable.AccountNum);
        metCBCTInvoiceLine.HeaderNumber             = _metCBCTInvoiceHeaderTable.Number;
        metCBCTInvoiceLine.VendCustType             = _metCBCTVendCust;

        if (_allocItemId)
        {
            metCBCTInvoiceLine.ItemId               = _allocItemId;
        }
        else
        {
            // CB411_412_ChargeThrough
            // This will default the default service item set on the selected vendor account based on if charge through allowed 
            // or cross dock allowed is enabled. If there is no service item defaulted, this field will be blank.
            if (_metCBCTInvoiceHeaderTable.InvoiceType == METInvoiceType::ChargeThrough)
            {
                metCBCTInvoiceLine.ItemId = metVendTable.ChargeThroughServiceItemId;
            }
            else
            {
                metCBCTInvoiceLine.ItemId = metVendTable.CrossDockServiceItemId;
            }
        }              
        metCBCTInvoiceLine.Qty                      = 1;
        metCBCTInvoiceLine.Amount                   = _amount;
        // CB411_412_ChargeThrough Defaults from the ‘Item sales tax group’ selected don the Released product record of the service item selected.
        //metCBCTInvoiceLine.TaxItemGroup             = _gstGroup;
        metCBCTInvoiceLine.TaxItemGroup             = InventTableModule::find(metCBCTInvoiceLine.ItemId, ModuleInventPurchSales::Sales).TaxItemGroupId;

        //metCBCTInvoiceLine.TaxGroup                 = _gstGroup;
        metCBCTInvoiceLine.TaxGroup                 = _taxGroup;

        metCBCTInvoiceLine.InventSiteId     = custTable.InventSiteId;
        metCBCTInvoiceLine.InventLocationId = custTable.InventLocation;
      
        
        // CB411_412_ChargeThrough call modifiedField so it sets financial dimension
        //metCBCTInvoiceLine.FinancialDimension   = METCBCTInvoiceLine::initFinancialDimension(metCBCTInvoiceLine.ItemId,_metCBCTInvoiceHeaderTable.FinancialDimension);
        metCBCTInvoiceLine.modifiedField(fieldNum(METCBCTInvoiceLine, ItemId));
        
        if (metCBCTInvoiceLine.validateWrite())
        {
            metCBCTInvoiceLine.insert();
        }
        else
        {
            error(strFmt("@MET:CBCTInvoiceLineValidateWrite", metCBCTInvoiceLine.VendCustType, metCBCTInvoiceLine.ItemId));
            ret = false;
        }

        return ret;
    }

    /// <summary>
    /// Create invoice line
    /// </summary>    
    /// <param name="_metCBCTInvoiceHeaderTable"><c>METCBCTInvoiceHeaderTable</c></param>    
    /// <param name="_gstPercent"><c>GSTPercent</c></param>
    /// <returns>True if CT lines are successfully created; otherwise, false.</returns>
    public boolean handleInvoiceLineCreation(METCBCTInvoiceHeaderTable _metCBCTInvoiceHeaderTable,
                                             Percent                   _gstPercent)
    {
        boolean allocation; 
        boolean ret = true;

        // CB194_ChargeThroughClaims
        // If the charge through reason code matches the code specified in the parameter, then only create a ‘customer’ line on the charge through lines
        METCustParameters   METCustParameters = METCustParameters::Find();
        boolean isCrossDockReasonCode = _metCBCTInvoiceHeaderTable.ClaimReasonCodeId == METCustParameters.CrossDockReturnReasonCodeId ? true : false;

        METVendParameters metVendParameters = METVendParameters::find();
        
        //check whether the allocation exist
        if (METCBCTDeptAllocTable::existVendor(_metCBCTInvoiceHeaderTable.VendorAccount))
        {
            if(METCBCTDeptAllocTable::getTotalAllocPctperVendor(_metCBCTInvoiceHeaderTable.VendorAccount) != 100)
            {
                error("@MET:AllocationPercentageNotFullyDefinedToMatch100Pct");
                return false;
            }
            else
            {
                allocation = true;
            }
        }
        // If the GST amount is exactly 10% of the net amount, create one line for customer and one line for vendor invoice, 
        // using the Item tax code of GST. If the vendor has a record in the “Vendor charge through allocation table” then split the line accordingly.
        if (_gstPercent == 10)
        {
            Amount  baseAmount = _metCBCTInvoiceHeaderTable.VendInvoiceAmtInclGST-_metCBCTInvoiceHeaderTable.VendInvoiceGSTAmount;
            if (allocation)
            {
                
                METCBCTDeptAllocTable   metCBCTDeptAllocTable;
                while select metCBCTDeptAllocTable
                    where metCBCTDeptAllocTable.VendAccount == _metCBCTInvoiceHeaderTable.VendorAccount
                {
                    Amount allocatedAmount = baseAmount* (metCBCTDeptAllocTable.AllocationPct/100);
                    ret = this.createInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Cust,allocatedAmount, metVendParameters.CreateLineGSTGroup, metCBCTDeptAllocTable.ServiceItemId);

                    if (!ret)
                    {
                        return ret;
                    }
                    else
                    {
                        if (!isCrossDockReasonCode)
                        {
                            ret = this.createInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Vend,allocatedAmount, metVendParameters.CreateLineGSTGroup, metCBCTDeptAllocTable.ServiceItemId);
                            if (!ret)
                            {
                                return ret;
                            }
                        }
                    }                   
                }
            }
            else
            {
                ret = this.createInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Cust,baseAmount, metVendParameters.CreateLineGSTGroup);
                if (!ret)
                {
                    return ret;
                }
                else
                {
                    if (!isCrossDockReasonCode)
                    {
                        ret = this.createInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Vend,baseAmount, metVendParameters.CreateLineGSTGroup);
                        if (!ret)
                        {
                            return ret;
                        }
                    }
                }
            }
        }
        else if (_gstPercent < 10) //The amount is more than the GST amount
        {
            Amount baseGstAmount        = _metCBCTInvoiceHeaderTable.VendInvoiceGSTAmount*10;
            Amount remainingBaseAmount  = this.getRemainingBaseAmount(_metCBCTInvoiceHeaderTable);
            if(allocation)
            {               
                
                METCBCTDeptAllocTable   metCBCTDeptAllocTable;
                while select metCBCTDeptAllocTable
                    where metCBCTDeptAllocTable.VendAccount == _metCBCTInvoiceHeaderTable.VendorAccount
                {
                    Amount allocatedBaseAmount      = baseGstAmount * (metCBCTDeptAllocTable.AllocationPct/100);
                    Amount allocatedRemainAmount    = remainingBaseAmount * (metCBCTDeptAllocTable.AllocationPct/100);  

                    ret = this.createInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Cust, allocatedBaseAmount, metVendParameters.CreateLineGSTGroup, metCBCTDeptAllocTable.ServiceItemId);
                    if (!ret)
                    {
                        return ret;
                    }
                    else
                    {
                        ret = this.createInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Cust, allocatedRemainAmount, metVendParameters.CreateLineGSTFreeGroup, metCBCTDeptAllocTable.ServiceItemId);
                        if (!ret)
                        {
                            return ret;
                        }
                        else
                        {
                            if (!isCrossDockReasonCode)
                            {
                                ret = this.createInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Vend, allocatedBaseAmount, metVendParameters.CreateLineGSTGroup, metCBCTDeptAllocTable.ServiceItemId);
                                if (!ret)
                                {
                                    return ret;
                                }
                                else
                                {
                                    ret = this.createInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Vend, allocatedRemainAmount, metVendParameters.CreateLineGSTFreeGroup, metCBCTDeptAllocTable.ServiceItemId);
                                    if (!ret)
                                    {
                                        return ret;
                                    }
                                }
                            }
                        }
                    }
                }
            }
            else
            {                
                ret = this.createInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Cust, baseGstAmount, metVendParameters.CreateLineGSTGroup);
                if (!ret)
                {
                    return ret;
                }
                else
                {
                    ret = this.createInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Cust, remainingBaseAmount, metVendParameters.CreateLineGSTFreeGroup);
                    if (!ret)
                    {
                        return ret;
                    }
                    else
                    {
                        if (!isCrossDockReasonCode)
                        {
                            ret = this.createInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Vend, baseGstAmount, metVendParameters.CreateLineGSTGroup);
                            if (!ret)
                            {
                                return ret;
                            }
                            else
                            {
                                ret = this.createInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Vend, remainingBaseAmount, metVendParameters.CreateLineGSTFreeGroup);
                                if (!ret)
                                {
                                    return ret;
                                }
                            }
                        }
                    }
                }
            }
        } 

        return ret;
    }
